importScripts(
    'https://storage.googleapis.com/workbox-cdn/releases/7.3.0/workbox-sw.js'
  );

  // ============================================================
  // BASIC CONFIGURATION
  // ============================================================

  self.skipWaiting();
  workbox.core.clientsClaim();

  // Precaching for static assets generated by Vite
  workbox.precaching.precacheAndRoute(self.__WB_MANIFEST || []);

  // ============================================================
  // RUNTIME CACHING STRATEGIES
  // ============================================================

  // 1️⃣ Cache API or dynamic JSON responses
  workbox.routing.registerRoute(
    ({ request }) => request.destination === 'document' || request.destination === 'script' || request.destination === 'style',
    new workbox.strategies.NetworkFirst({
      cacheName: 'dynamic-pages',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 50,
          maxAgeSeconds: 60 * 60 * 24 // 1 day
        })
      ]
    })
  );

  // 2️⃣ Cache images/icons for offline usage
  workbox.routing.registerRoute(
    ({ request }) => request.destination === 'image',
    new workbox.strategies.CacheFirst({
      cacheName: 'images',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 100,
          maxAgeSeconds: 7 * 24 * 60 * 60 // 1 week
        })
      ]
    })
  );

  // 3️⃣ Cache fonts (Google Fonts, etc.)
  workbox.routing.registerRoute(
    ({ url }) => url.origin.includes('fonts.googleapis.com') || url.origin.includes('fonts.gstatic.com'),
    new workbox.strategies.CacheFirst({
      cacheName: 'fonts',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 20,
          maxAgeSeconds: 365 * 24 * 60 * 60 // 1 year
        })
      ]
    })
  );

  // ============================================================
  // VERSION & UPDATE HANDLING
  // ============================================================

 // ============================================================
// VERSION & UPDATE HANDLING (FIXED)
// ============================================================

// Force activate immediately
self.addEventListener('install', (event) => {
    console.log('🔧 Service Worker installing...');
    self.skipWaiting();
  });

  self.addEventListener('activate', (event) => {
    console.log('✅ Service Worker activated');
    event.waitUntil(self.clients.claim());
  });

  // Listen for manual skipWaiting command from the app
  self.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'SKIP_WAITING') {
      console.log('⚡ skipWaiting message received');
      self.skipWaiting();
    }
  });




  // ============================================================
  // WIDGET EVENTS (keep your logic intact)
  // ============================================================

  self.addEventListener('widgetinstall', (event) => {
    event.waitUntil(updateWidget(event));
  });

  self.addEventListener('widgetresume', (event) => {
    event.waitUntil(updateWidget(event));
  });

  self.addEventListener('widgetclick', (event) => {
    if (event.action == 'updateName') {
      event.waitUntil(updateName(event));
    }
  });

  self.addEventListener('widgetuninstall', (event) => {
    // Cleanup if needed
  });

  const updateWidget = async (event) => {
    const widgetDefinition = event.widget.definition;
    const payload = {
      template: JSON.stringify(await (await fetch(widgetDefinition.msAcTemplate)).json()),
      data: JSON.stringify(await (await fetch(widgetDefinition.data)).json())
    };
    await self.widgets.updateByInstanceId(event.instanceId, payload);
  };

  const updateName = async (event) => {
    const name = event.data.json().name;
    const widgetDefinition = event.widget.definition;
    const payload = {
      template: JSON.stringify(await (await fetch(widgetDefinition.msAcTemplate)).json()),
      data: JSON.stringify({ name })
    };
    await self.widgets.updateByInstanceId(event.instanceId, payload);
  };

  // ============================================================
  // OFFLINE FALLBACK PAGE (Optional)
  // ============================================================

  // Example: If you want an offline fallback (offline.html)
  const FALLBACK_URL = '/offline.html';
  workbox.routing.setCatchHandler(async ({ event }) => {
    if (event.request.destination === 'document') {
      return workbox.precaching.matchPrecache(FALLBACK_URL);
    }
    return Response.error();
  });

  console.log('🚀 Optimized Service Worker loaded');
